text:
Here's the full `api.js` — now with a built-in offline interceptor. The `request()` function gains a route-matching layer that caches online responses and falls back to IndexedDB when offline. All 25+ existing exports stay **exactly as they are** — no page imports change.

```js
const API_BASE = import.meta.env.VITE_API_URL || '';

import { db } from '../db/localDB';
import * as offline from '../sync/offlineMutations';

// ── Single source of truth for offline-synced routes ──
// Add one entry per URL pattern when adding new entity types.
// `:param` segments match any non-slash value.
// `list: true` means GET returns an array; `false` means a single object.
// `complex: true` means the response shape can't be decomposed into
// individual entities — it's cached as a raw blob.
// Omit from this array = never intercepted (auth, face rec, QR, chat).

const SYNCED_ROUTES = [
  // Programmes
  { pattern: '/programmes',                     type: 'programme',     list: true },
  { pattern: '/programmes/:id',                 type: 'programme' },
  // Routes
  { pattern: '/programmes/:id/routes',           type: 'route',        list: true },
  { pattern: '/programmes/:id/routes/:routeId',  type: 'route' },
  { pattern: '/programmes/:id/routes/:routeId/archive',  type: 'route' },
  { pattern: '/programmes/:id/routes/:routeId/restore',  type: 'route' },
  // Delegates
  { pattern: '/programmes/:id/delegates',        type: 'delegate',     list: true },
  { pattern: '/programmes/:id/delegates/:delegateId', type: 'delegate' },
  { pattern: '/delegates/:delegateId',           type: 'delegate' },
  { pattern: '/programmes/:id/delegates/:delegateId/routes', type: 'delegate' },
  // Attendance
  { pattern: '/programmes/:id/attendance',       type: 'attendance',   list: true, complex: true },
  { pattern: '/programmes/:id/attendance/:delegateId', type: 'attendance', upsert: true },
  { pattern: '/programmes/:id/attendance/summary',     type: 'attendance', complex: true },
  // Ready to depart
  { pattern: '/programmes/:id/routes/:routeId/ready-to-depart', type: 'readyToDepart' },
];

// ── Pattern matching ──

function matchRoute(path) {
  const clean = path.split('?')[0];
  for (const route of SYNCED_ROUTES) {
    const parts = route.pattern.split('/');
    const segs = clean.split('/');
    if (parts.length !== segs.length) continue;
    const params = {};
    let ok = true;
    for (let i = 0; i < parts.length; i++) {
      if (parts[i].startsWith(':')) params[parts[i].slice(1)] = segs[i];
      else if (parts[i] !== segs[i]) { ok = false; break; }
    }
    if (ok) return { ...route, params };
  }
  return null;
}

// ── Cache helpers ──

async function cacheAsEntities(type, records) {
  if (!records) return;
  const items = Array.isArray(records) ? records : [records];
  await db.transaction('rw', db.entities, async () => {
    await db.entities.where({ type, status: 'synced' }).delete();
    await db.entities.bulkAdd(items.map(r => ({
      localId: crypto.randomUUID(),
      serverId: r.id ?? null,
      type,
      status: 'synced',
      ...r,
    })));
  });
}

async function cacheAsBlob(path, data) {
  await db.responseCache.put({ path, data, cachedAt: Date.now() });
}

function stripMeta(e) {
  const { localId, serverId, type, status, ...rest } = e;
  if (serverId) rest.id = serverId;
  return rest;
}

// ── Core interceptor ──

async function request(method, path, body) {
  const route = matchRoute(path);

  // ── ONLINE PATH ──
  if (navigator.onLine) {
    try {
      const opts = { method, headers: { 'Content-Type': 'application/json' } };
      if (body !== undefined) opts.body = JSON.stringify(body);
      const res = await fetch(`${API_BASE}${path}`, opts);
      if (res.status === 204) return null;
      const text = await res.text();
      if (!text) {
        if (!res.ok) throw new Error(`Request failed (${res.status})`);
        return null;
      }
      let data;
      try { data = JSON.parse(text); } catch { data = null; }
      if (!res.ok) throw new Error(data?.error || `Request failed (${res.status})`);

      // Cache successful GET responses for offline use
      if (route && method === 'GET' && data !== null) {
        if (route.complex) {
          await cacheAsBlob(path, data);
        } else {
          await cacheAsEntities(route.type, data);
        }
      }
      return data;
    } catch (err) {
      if (!route) throw err;
      // Fall through to offline path
    }
  }

  // ── OFFLINE PATH (synced routes only) ──
  if (!route) throw new Error('This operation requires a network connection');

  if (method === 'GET') {
    if (route.complex) {
      const cached = await db.responseCache.get(path);
      if (!cached) throw new Error('No cached data available offline');
      return cached.data;
    }
    if (route.list) {
      const items = await db.entities
        .where({ type: route.type })
        .filter(e => e.status !== 'deleted')
        .toArray();
      return items.map(stripMeta);
    }
    // Single entity: last `:id` or `:*Id` param is the server ID
    const id = Object.values(route.params).pop();
    const item = await db.entities
      .where({ type: route.type, serverId: id })
      .first();
    if (!item) throw new Error('Not found in local cache');
    return stripMeta(item);
  }

  // Offline writes
  if (method === 'POST' || method === 'PUT' || method === 'PATCH') {
    // Batch attendance
    if (route.type === 'attendance' && body?.records) {
      const results = [];
      for (const rec of body.records) {
        await offline.upsertLocal('attendance', { programmeId: route.params.id, ...rec });
        results.push({ delegateId: rec.delegateId, ...rec });
      }
      return { success: results, errors: [] };
    }

    // Upsert (attendance by programmeId + delegateId)
    if (route.upsert) {
      await offline.upsertLocal(route.type, { programmeId: route.params.id, delegateId: route.params.delegateId, ...body });
      return { programmeId: route.params.id, delegateId: route.params.delegateId, ...body };
    }

    // Update by ID
    const id = Object.values(route.params).pop();
    if (id) {
      await offline.updateLocal(route.type, id, body || {});
      return { id, ...body };
    }

    // Create (no serverId yet)
    await offline.createLocal(route.type, body);
    return { localId: crypto.randomUUID(), ...body };
  }

  if (method === 'DELETE') {
    const id = Object.values(route.params).pop();
    await offline.deleteLocal(route.type, id);
    return null;
  }

  throw new Error(`Unsupported ${method} ${path} while offline`);
}

// ── Auth-required requests (never intercepted) ──

async function requestWithAuth(method, path, body, token) {
  const opts = {
    method,
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
  };
  if (body !== undefined) opts.body = JSON.stringify(body);
  const res = await fetch(`${API_BASE}${path}`, opts);
  if (res.status === 204) return null;
  const text = await res.text();
  if (!text) {
    if (!res.ok) throw new Error(`Request failed (${res.status})`);
    return null;
  }
  let data;
  try { data = JSON.parse(text); } catch { data = null; }
  if (!res.ok) throw new Error(data?.error || `Request failed (${res.status})`);
  return data;
}

// ══════════════════════════════════════════════════════════
//  EXISTING EXPORTS — unchanged. Pages keep importing these.
// ══════════════════════════════════════════════════════════

// Programmes
export const getProgrammes = () => request('GET', '/programmes');
export const createProgramme = (data) => request('POST', '/programmes', data);
export const updateProgramme = (id, data) => request('PUT', `/programmes/${id}`, data);
export const deleteProgramme = (id) => request('DELETE', `/programmes/${id}`);

// Routes
export const getRoutes = (id, archived) => {
  const qs = archived ? "?archived=true" : "";
  return request('GET', `/programmes/${id}/routes${qs}`);
};
export const addRoute = (id, data) => request('POST', `/programmes/${id}/routes`, data);
export const getRoute = (id, routeId) => request('GET', `/programmes/${id}/routes/${routeId}`);
export const updateRoute = (id, routeId, data) => request('PUT', `/programmes/${id}/routes/${routeId}`, data);
export const deleteRoute = (id, routeId) => request('DELETE', `/programmes/${id}/routes/${routeId}`);
export const archiveRoute = (id, routeId) => request('PUT', `/programmes/${id}/routes/${routeId}/archive`);
export const restoreRoute = (id, routeId) => request('PUT', `/programmes/${id}/routes/${routeId}/restore`);

// Delegates
export const getDelegates = (id) => request('GET', `/programmes/${id}/delegates`);
export const addDelegate = (id, data) => request('POST', `/programmes/${id}/delegates`, data);
export const removeDelegate = (id, delegateId) => request('DELETE', `/programmes/${id}/delegates/${delegateId}`);

// Route members
export const setDelegateRoutes = (id, delegateId, routeIds) =>
  request('PUT', `/programmes/${id}/delegates/${delegateId}/routes`, { routeIds });
export const getDelegateRoutes = (id, delegateId) =>
  request('GET', `/programmes/${id}/delegates/${delegateId}/routes`);

// Attendance
export const getAttendance = (id) => request('GET', `/programmes/${id}/attendance`);
export const getAttendanceSummary = (id) => request('GET', `/programmes/${id}/attendance/summary`);
export const markAttendance = (id, delegateId, data) =>
  request('PUT', `/programmes/${id}/attendance/${delegateId}`, data);

// Batch attendance
export const markAttendanceBatch = (id, records) =>
  request('POST', `/programmes/${id}/attendance`, { records });

// Ready to depart
export const getReadyStatus = (id, routeId) =>
  request('GET', `/programmes/${id}/routes/${routeId}/ready-to-depart`);
export const toggleReady = (id, routeId, data) =>
  request('PUT', `/programmes/${id}/routes/${routeId}/ready-to-depart`, data);

// Face recognition (never intercepted — not in SYNCED_ROUTES)
export const recognizeFaces = (id, image) =>
  request('POST', `/programmes/${id}/recognize`, { image });

// QR badge lookup (never intercepted)
export const lookupByBadge = (id, badge) =>
  request('POST', `/programmes/${id}/scan-qr`, { badge });
export const lookupBadges = (id, badges) =>
  request('POST', `/programmes/${id}/scan-qr`, { badges });

// Users (never intercepted)
export const getUsers = () => request('GET', '/users');

// Auth (never intercepted — uses requestWithAuth)
export const uploadUserFace = (userId, image, token) =>
  requestWithAuth('PATCH', `/api/user/${userId}/face/default`, { image }, token);
export const authLogin = (data) => request('POST', '/api/auth/login', data);
export const updateUserProfile = (data, token) =>
  requestWithAuth('PATCH', '/api/auth', data, token);
export const deleteUserAccount = (data, token) =>
  requestWithAuth('DELETE', '/api/auth', data, token);
export const getAllUsers = (token) =>
  requestWithAuth('GET', '/api/auth/all', undefined, token);
export const createUserAccount = (data, token) =>
  requestWithAuth('POST', '/api/auth', data, token);
```

---

**Key design properties:**

| Concern | How it's handled |
|---|---|
| Adding a new entity type | One new entry in `SYNCED_ROUTES` |
| Adding a new endpoint for an existing type | One new export + route entry if the URL pattern is new |
| Auth / face / QR / chat | Not in `SYNCED_ROUTES` → never intercepted, throws if offline |
| Complex shapes (attendance, summary) | `complex: true` → cached as raw blob, not decomposed |
| Attendance upsert | `upsert: true` → calls `offline.upsertLocal()` by programmeId+delegateId |
| Batch attendance offline | Detects `body.records`, queues each as individual upsert |
| URL query params (e.g. `?archived=true`) | Stripped before matching; offline reads ignore them (returns all) |
| `requestWithAuth` | Completely separate function, never touched |
| Optimistic offline writes | Returns a fake success shape so calling code doesn't crash |
| Cache invalidation | Replaced entirely by full sync + on each online GET |

The tradeoff vs the per-wrapper `offlineApi.js` approach: offline reads of complex shapes (`attendance`, `summary`) return the last cached blob rather than a real-time reconstructed view. Offline writes queue but don't eagerly update those blobs — the next sync replaces them. For simple entity types (programme, route, delegate, readyToDepart), offline reads are always current because individual entities are cached and updated inline.

