```js
const API_BASE = import.meta.env.VITE_API_URL || '';
import { db } from '../db/localDB';

// Paths that support offline operation (queue writes / cache reads)
const SYNCED_PREFIXES = ['/programmes', '/delegates'];

function isSynced(path) {
  return SYNCED_PREFIXES.some(p => path.startsWith(p));
}

async function request(method, path, body) {
  const opts = { method, headers: { 'Content-Type': 'application/json' } };
  if (body !== undefined) opts.body = JSON.stringify(body);

  // Try online first
  if (navigator.onLine) {
    try {
      const res = await fetch(`${API_BASE}${path}`, opts);
      if (res.status === 204) return null;
      const text = await res.text();
      if (!text) { if (!res.ok) throw new Error(`Request failed (${res.status})`); return null; }
      let data;
      try { data = JSON.parse(text); } catch { data = null; }
      if (!res.ok) throw new Error(data?.error || `Request failed (${res.status})`);

      // Cache GET responses for offline reads
      if (method === 'GET' && data !== null && isSynced(path)) {
        await db.requestCache.put({ path: path.split('?')[0], data, cachedAt: Date.now() });
      }
      return data;
    } catch (err) {
      if (!isSynced(path)) throw err;
    }
  }

  // Offline
  if (!isSynced(path)) throw new Error('Network required');

  if (method === 'GET') {
    const cached = await db.requestCache.get(path.split('?')[0]);
    if (!cached) throw new Error('Not available offline');
    return cached.data;
  }

  // Offline write: queue for sync, return fake success
  const pc = await db.pendingChanges.get('current') || { id: 'current', changes: [], timestamp: 0 };
  pc.changes.push({ method, path, body: body || null });
  pc.timestamp = Date.now();
  await db.pendingChanges.put(pc);

  if (method === 'DELETE') return null;
  if (body) return { ...body, id: body.id || 'pending' };
  return { id: 'pending' };
}
```

