import Dexie from 'dexie';

export const db = new Dexie('OpenGlimpseDB');

db.version(1).stores({
  requestCache:   'path',
  pendingChanges: 'id'
});

import { db } from '../db/localDB';

const API_BASE = import.meta.env.VITE_API_URL || '';

export async function changeHandler() {
  const pc = await db.pendingChanges.get('current');
  if (!pc || pc.ops.length === 0) return;

  const res = await fetch(`${API_BASE}/sync`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ ops: pc.ops, timestamp: pc.timestamp })
  });

  if (!res.ok) {
    throw new Error('Sync failed');
  }

  await db.pendingChanges.delete('current');
}

import { useEffect, useRef } from 'react';
import { changeHandler } from '../sync/syncEngine';

export function useSync() {
  const syncing = useRef(false);

  useEffect(() => {
    const sync = async () => {
      if (syncing.current) return;
      syncing.current = true;
      try {
        await changeHandler();
      } catch {
      } finally {
        syncing.current = false;
      }
    };

    sync();

    window.addEventListener('online', sync);
    window.addEventListener('focus', sync);

    return () => {
      window.removeEventListener('online', sync);
      window.removeEventListener('focus', sync);
    };
  }, []);
}

import { useState, useEffect } from 'react';
import { db } from '../db/localDB';

export function useConnectivity() {
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isSyncing, setIsSyncing] = useState(false);
  const [pendingCount, setPendingCount] = useState(0);

  useEffect(() => {
    const updatePending = async () => {
      const pc = await db.pendingChanges.get('current');
      setPendingCount(pc ? pc.ops.length : 0);
    };

    const goOnline = () => {
      setIsOnline(true);
      updatePending();
    };

    const goOffline = () => {
      setIsOnline(false);
    };

    window.addEventListener('online', goOnline);
    window.addEventListener('offline', goOffline);

    updatePending();
    const interval = setInterval(updatePending, 3000);

    return () => {
      window.removeEventListener('online', goOnline);
      window.removeEventListener('offline', goOffline);
      clearInterval(interval);
    };
  }, []);

  return { isOnline, isSyncing, pendingCount };
}

import { useConnectivity } from '../../hooks/useConnectivity';

export default function ConnectivityIndicator() {
  const { isOnline, isSyncing, pendingCount } = useConnectivity();

  if (isSyncing) {
    return (
      <div className="connectivity-indicator syncing">
        Syncing...
      </div>
    );
  }

  if (!isOnline) {
    return (
      <div className="connectivity-indicator offline">
        Offline &mdash; {pendingCount} pending change{pendingCount !== 1 ? 's' : ''}
      </div>
    );
  }

  return null;
}

