const API_BASE = import.meta.env.VITE_API_URL || '';
import { db } from '../db/localDB';

const SYNCED_PREFIXES = ['/programmes', '/delegates'];

function isSynced(path) {
  return SYNCED_PREFIXES.some(p => path.startsWith(p));
}

async function request(method, path, body) {
  const opts = {
    method,
    headers: { 'Content-Type': 'application/json' }
  };
  if (body !== undefined) {
    opts.body = JSON.stringify(body);
  }

  if (navigator.onLine) {
    try {
      const res = await fetch(`${API_BASE}${path}`, opts);
      if (res.status === 204) {
        return null;
      }
      const text = await res.text();
      if (!text) {
        if (!res.ok) {
          throw new Error(`Request failed (${res.status})`);
        }
        return null;
      }
      let data;
      try {
        data = JSON.parse(text);
      } catch {
        data = null;
      }
      if (!res.ok) {
        throw new Error(data?.error || `Request failed (${res.status})`);
      }
      if (method === 'GET' && data !== null && isSynced(path)) {
        await db.requestCache.put({
          path: path.split('?')[0],
          data
        });
      }
      return data;
    } catch (err) {
      if (!isSynced(path)) {
        throw err;
      }
    }
  }

  if (!isSynced(path)) {
    throw new Error('Network required');
  }

  if (method === 'GET') {
    const cached = await db.requestCache.get(path.split('?')[0]);
    if (!cached) {
      throw new Error('Not available offline');
    }
    return cached.data;
  }

  const pc = await db.pendingChanges.get('current') || {
    id: 'current',
    ops: [],
    timestamp: 0
  };
  pc.ops.push({ method, path, body: body || null });
  pc.timestamp = Date.now();
  await db.pendingChanges.put(pc);

  if (method === 'DELETE') {
    return null;
  }
  return body
    ? { ...body, id: body.id || 'pending' }
    : { id: 'pending' };
}

